  1	import * as vscode from "vscode";
  2	import * as path from "node:path";
  3	import * as fs from "node:fs";
  4	import { VSCodeSettings } from "./config/vscode-settings";
  5	import { getCLIManager, FileManager } from "./managers";
  6	import { handlers, type HandlerContext, type BroadcastFn, type ReloadWebviewFn, type ShowLogsFn } from "./handlers";
  7	import { createSession, parseConfig, getModelThinkingMode, getModelById, type Session, type Turn } from "@consilium/agent-sdk";
  8	import { readSessionTitle, writeSessionTitle, readThinkSessionTitle, writeThinkSessionTitle } from "./lib/session-storage";
  9	import type { SessionMetadata } from "../shared/types";
 10	import { sessionLog } from "./utils/logger.js";
