102	export class BridgeHandler {
103	  private sessions = new Map<string, Session>();
104	  private turns = new Map<string, Turn>();
105	  private customWorkDirs = new Map<string, string>(); // webviewId -> custom workDir
106	  private fileManager: FileManager;
107	  private activeTabs = new Map<string, 'think' | 'do'>();
108	
109	  constructor(
110	    private broadcast: BroadcastFn,
111	    private workspaceState: vscode.Memento,
112	    private globalState: vscode.Memento,
113	    private reloadWebview: ReloadWebviewFn,
114	    private showLogs: ShowLogsFn,
115	    private extensionRoot: string,
116	  ) {
117	    this.fileManager = new FileManager(() => this.workspaceRoot, broadcast);
118	    
119	    // PERSISTENCE TEST
120	    const testKey = 'consilium-persistence-test-v2';
121	    const existing = this.workspaceState.get(testKey, 0) as number;
122	    sessionLog.log("PERSISTENCE TEST", { existing });
123	    this.workspaceState.update(testKey, existing + 1).then(() => {
124	      sessionLog.log("PERSISTENCE TEST updated", { value: existing + 1 });
125	    });
126	  }
127	
128	  async handle(msg: RpcMessage, webviewId: string): Promise<RpcResult> {
129	    try {
130	      if (msg.method === "setActiveTab") {
131	        const { tab } = (msg.params as any) || {};
132	        sessionLog.log("SETTING activeTab", { webviewId, tab });
133	        this.activeTabs.set(webviewId, tab);
134	        await this.persistTabState(webviewId);
135	        return { id: msg.id, result: { ok: true, setTo: tab } };
136	      }
137	
138	      sessionLog.log("handle RPC", { method: msg.method, webviewId, activeTab: this.activeTabs.get(webviewId) ?? 'default-think' });
139	      return {
140	        id: msg.id,
141	        result: await this.dispatch(msg.method, msg.params, webviewId),
142	      };
143	    } catch (err) {
144	      return {
145	        id: msg.id,
146	        error: err instanceof Error ? err.message : String(err),
147	      };
148	    }
149	  }
150	
151	  private getSessionKey(webviewId: string): string {
152	    const tab = this.activeTabs.get(webviewId) ?? 'think';
153	    const key = tab === 'think' ? webviewId : `${webviewId}:do`;
154	    sessionLog.log("getSessionKey", { webviewId, tab, key });
155	    return key;
156	  }
157	
158	  private tabStateKey(webviewId: string): string {
159	    const type = webviewId.startsWith('sidebar') ? 'sidebar' : 'panel';
160	    return `consilium-dual-tab-state-${type}`;
161	  }
162	
163	  private persistTabState(webviewId: string): void {
164	    const thinkSession = this.sessions.get(webviewId);
165	    const doSession = this.sessions.get(`${webviewId}:do`);
166	    const activeTab = this.activeTabs.get(webviewId) ?? 'think';
167	    const data = {
168	      thinkSessionId: thinkSession?.sessionId ?? null,
169	      doSessionId: doSession?.sessionId ?? null,
170	      activeTab,
171	    };
172	    sessionLog.log("persistTabState", { webviewId, data });
173	    this.workspaceState.update(this.tabStateKey(webviewId), data);
174	  }
175	
176	  private restoreTabState(webviewId: string): { thinkSessionId?: string; doSessionId?: string; activeTab?: 'think' | 'do' } {
177	    return this.workspaceState.get(this.tabStateKey(webviewId), {});
178	  }
179	
180	  public setSessionMetadata(sessionId: string, meta: SessionMetadata, workDir?: string): void {
181	    const isThink = meta.mode === "think";
182	
183	    // Write title to authoritative file storage when possible.
184	    // An empty string title intentionally clears a previously set title.
185	    if (isThink) {
186	      writeThinkSessionTitle(
187	        sessionId,
188	        meta.title ?? "",
189	        meta.titleSource ?? "user",
190	        meta.titleGeneratedAt,
191	        workDir,
192	      );
193	    } else if (workDir) {
194	      writeSessionTitle(
195	        workDir,
196	        sessionId,
197	        meta.title ?? "",
198	        meta.titleSource ?? "user",
199	        meta.titleGeneratedAt,
200	      );
201	    }
202	
203	    // Keep globalState as the source of truth for mode and as a fallback/cache.
204	    const key = `consilium-session-meta-${sessionId}`;
205	    const existing: SessionMetadata | undefined = this.globalState.get(key);
206	    this.globalState.update(key, { ...existing, ...meta });
207	  }
208	
209	  public getSessionMetadata(sessionId: string, workDir?: string): SessionMetadata | undefined {
210	    // Start from legacy globalState sidecar for mode and fallback title.
211	    const key = `consilium-session-meta-${sessionId}`;
212	    const sidecar: SessionMetadata | undefined = this.globalState.get(key);
213	    const isThink = sidecar?.mode === "think";
214	
215	    // Prefer file-based title storage.
216	    if (!isThink && workDir) {
217	      const fileTitle = readSessionTitle(workDir, sessionId);
218	      if (fileTitle) {
219	        return {
220	          mode: sidecar?.mode,
221	          title: fileTitle.title,
222	          titleSource: fileTitle.source,
223	          titleGeneratedAt: fileTitle.generatedAt,
224	        };
225	      }
226	    }
227	
228	    const thinkTitle = readThinkSessionTitle(sessionId, workDir);
229	    if (thinkTitle) {
230	      return {
231	        mode: sidecar?.mode ?? "think",
232	        title: thinkTitle.title,
233	        titleSource: thinkTitle.source,
234	        titleGeneratedAt: thinkTitle.generatedAt,
235	      };
236	    }
237	
238	    return sidecar;
239	  }
240	
241	  private get workspaceRoot(): string | null {
242	    return vscode.workspace.workspaceFolders?.[0]?.uri.fsPath ?? null;
243	  }
244	
245	  private getWorkDir(webviewId: string): string | null {
246	    return this.customWorkDirs.get(webviewId) ?? this.workspaceRoot;
247	  }
248	
249	  setCustomWorkDir(webviewId: string, workDir: string | null): void {
250	    if (workDir && workDir !== this.workspaceRoot) {
251	      this.customWorkDirs.set(webviewId, workDir);
252	    } else {
253	      this.customWorkDirs.delete(webviewId);
254	    }
255	    // Close sessions when workDir changes
256	    this.sessions.get(webviewId)?.close();
257	    this.sessions.delete(webviewId);
258	    this.turns.delete(webviewId);
259	
260	    const doKey = `${webviewId}:do`;
261	    this.sessions.get(doKey)?.close();
262	    this.sessions.delete(doKey);
263	    this.turns.delete(doKey);
264	
265	    this.fileManager.clearTracked(webviewId);
266	    this.fileManager.clearTracked(doKey);
267	  }
268	
269	  private requireWorkDir(webviewId: string): string {
270	    const w = this.getWorkDir(webviewId);
271	    if (!w) {
272	      throw new Error("No workspace folder open");
273	    }
274	    return w;
275	  }
276	
277	  private async dispatch(method: string, params: unknown, webviewId: string): Promise<unknown> {
278	    const handler = handlers[method];
279	    if (!handler) {
280	      throw new Error(`Unknown method: ${method}`);
281	    }
282	    return handler(params, this.createContext(webviewId));
283	  }
284	
285	  private createContext(webviewId: string): HandlerContext {
286	    return {
287	      webviewId,
