import { useEffect, useState, useCallback } from "react";
import { Header } from "./components/Header";
import { ChatArea } from "./components/ChatArea";
import { InputArea } from "./components/inputarea/InputArea";
import { MCPServersModal } from "./components/MCPServersModal";
import { WorkDirModal } from "./components/WorkDirModal";
import { ConfigErrorScreen } from "./components/ConfigErrorScreen";
import { SetupScreen } from "./components/SetupScreen";
import { Toaster, toast } from "./components/ui/sonner";
import { useChatStore, useSettingsStore } from "./stores";
import { bridge, Events } from "./services";
import { useAppInit } from "./hooks/useAppInit";
import { isPreflightError } from "shared/errors";
import type { UIStreamEvent, StreamError, ExtensionConfig } from "shared/types";
import "./styles/index.css";

function MainContent({ onAuthAction }: { onAuthAction: () => void }) {
  const { processEvent, startNewConversation, sessionId, setTitle } = useChatStore();
  const { setMCPServers, setExtensionConfig, extensionConfig } = useSettingsStore();

  useEffect(() => {
    // Batch events via requestAnimationFrame to prevent main thread saturation
    // during high-frequency streams (thinking tokens, tool call parts).
    let pendingEvents: UIStreamEvent[] = [];
    let flushScheduled = false;

    const flush = () => {
      flushScheduled = false;
      const batch = pendingEvents;
      pendingEvents = [];
      if (batch.length === 0) return;

      // Process all buffered events in a single state update
      for (const event of batch) {
        processEvent(event);
      }

      // Handle errors from the batch
      for (const event of batch) {
        if (event.type === "error") {
          const streamError = event as StreamError;
          if (isPreflightError(streamError.code || "UNKNOWN")) {
            toast.error(streamError.message);
          }
        }
      }
    };

    const scheduleFlush = () => {
      if (flushScheduled) return;
      flushScheduled = true;
      if (typeof requestAnimationFrame !== "undefined") {
        requestAnimationFrame(flush);
      } else {
        setTimeout(flush, 0);
      }
    };

    return bridge.on(Events.StreamEvent, (event: UIStreamEvent) => {
      // 只有当前已有 session 时才过滤，确保 session_start 能正常处理
      if (sessionId && "_sessionId" in event && event._sessionId && event._sessionId !== sessionId) {
        console.log("Ignored stream event from another session:", event._sessionId);
        return;
      }
      pendingEvents.push(event);
      scheduleFlush();
    });
  }, [processEvent, sessionId]);

  useEffect(() => {
    const unsubs = [
      bridge.on(Events.MCPServersChanged, setMCPServers),
      bridge.on(Events.ExtensionConfigChanged, ({ config }: { config: ExtensionConfig }) => setExtensionConfig(config)),
      bridge.on(Events.FocusInput, () => document.querySelector<HTMLTextAreaElement>("textarea")?.focus()),
      bridge.on(Events.NewConversation, () => startNewConversation()),
      bridge.on(Events.SessionTitleUpdated, ({ sessionId: updatedSessionId, title, source }: { sessionId: string; title: string; source: "user" | "llm" | "fallback" }) => {
        setTitle(updatedSessionId, title, source);
      }),
    ];
    return () => unsubs.forEach((u) => u());
  }, [setMCPServers, setExtensionConfig, startNewConversation, setTitle]);

  useEffect(() => {
    useChatStore.getState().initTabs();
  }, []);

  useEffect(() => {
    if (!extensionConfig.enableNewConversationShortcut) return;
    const handler = (e: KeyboardEvent) => {
      if ((e.metaKey || e.ctrlKey) && e.key === "n") {
        e.preventDefault();
        startNewConversation();
      }
    };
    window.addEventListener("keydown", handler);
    return () => window.removeEventListener("keydown", handler);
  }, [extensionConfig.enableNewConversationShortcut, startNewConversation]);

  return (
    <>
      <div className="flex-1 min-h-0 relative group/chat">
        <ChatArea />
      </div>
      <div className="shrink-0 max-h-[80vh] flex flex-col min-h-0">
        <InputArea onAuthAction={onAuthAction} />
      </div>
      <MCPServersModal />
      <WorkDirModal />
    </>
  );
}

export default function App() {
  const { status, errorMessage, cliResult, modelsCount, refresh } = useAppInit();
  const extensionConfig = useSettingsStore((s) => s.extensionConfig);
  const [forceShowSetup, setForceShowSetup] = useState(false);

  const handleSetupSuccess = useCallback(() => {
    setForceShowSetup(false);
    refresh();
  }, [refresh]);

  // Show setup screen if no API key is configured or if explicitly requested
  const hasApiKey = !!extensionConfig?.apiKey;
  const shouldShowSetup = !hasApiKey || forceShowSetup;

  if (shouldShowSetup && status !== "loading" && status !== "cli-error" && status !== "no-workspace") {
    return (
      <div className="flex flex-col h-screen text-foreground overflow-hidden">
        <Header />
        <SetupScreen onSetupSuccess={handleSetupSuccess} />
        <Toaster position="top-center" />
      </div>
    );
  }

  // 如果没有模型
  if (modelsCount === 0 && status === "no-models") {
    return (
      <div className="flex flex-col h-screen text-foreground overflow-hidden">
        <Header />
        <ConfigErrorScreen type="no-models" cliResult={cliResult} errorMessage={errorMessage} onRefresh={refresh} onOpenSetup={() => setForceShowSetup(true)} />
        <Toaster position="top-center" />
      </div>
    );
  }

  // 其他错误状态
  if (status === "cli-error" || status === "no-workspace") {
    return (
      <div className="flex flex-col h-screen text-foreground overflow-hidden">
        <Header />
        <ConfigErrorScreen type={status} cliResult={cliResult} errorMessage={errorMessage} />
        <Toaster position="top-center" />
      </div>
    );
  }

  // 正常状态
  return (
    <div className="flex flex-col h-screen text-foreground overflow-hidden">
      <Header />
      <MainContent onAuthAction={() => setForceShowSetup(true)} />
      <Toaster position="top-center" />
    </div>
  );
}
